7	/**
8	 * Maps a CSV line ("symbol,price,volume") to a {@link PriceEvent}. Wired as the file feed's
9	 * valueMapper, so the hosted graph receives typed PriceEvents rather than raw Strings.
10	 * Implements {@code Function<Object,?>} (the feed-wrapper's value type) and tolerates blank or
11	 * short lines (e.g. a trailing newline) so the feed never throws.
12	 */
13	public class CsvToPriceEvent implements Function<Object, PriceEvent> {
14	
15	    @Override
16	    public PriceEvent apply(Object event) {
17	        String line = String.valueOf(event);
18	        String[] f = line.split(",");
19	        if (f.length < 3) {
20	            return new PriceEvent(line.trim(), 0.0, 0L);
21	        }
22	        return new PriceEvent(f[0].trim(), Double.parseDouble(f[1].trim()), Long.parseLong(f[2].trim()));
23	    }
24	}
